// Inlines Leaflet into a JS module so the ride map works inside a WebView without a CDN.
// Run with: npm run generate
import fs from 'node:fs';
const js = fs.readFileSync('node_modules/leaflet/dist/leaflet.js', 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync('node_modules/leaflet/dist/leaflet.css', 'utf8');
fs.writeFileSync(
  'src/leafletBundle.js',
  '// GENERATED by scripts/build-leaflet.mjs — Leaflet 1.9.4 (BSD-2-Clause, (c) Volodymyr Agafonkin)\n' +
    `export const LEAFLET_JS = ${JSON.stringify(js)};\n` +
    `export const LEAFLET_CSS = ${JSON.stringify(css)};\n`
);
